int insere(int A[], int *n, int C, int x) {
    if (*n >= C) return 0;
    int i = *n;
    while (i > 0 && A[i-1] > x) {
        A[i] = A[i-1];
        --i;
    }
    A[i] = x;
    ++*n;
    return 1;
}

